export function corsHeaders(origin: string | null): Record<string, string> {
  // native mobile clients do not send a fixed origin
  return {
    "Access-Control-Allow-Origin": origin ?? "*",
    "Access-Control-Allow-Credentials": "true",
    Vary: "Origin",
  };
}
